import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"论文叙事六大范式","description":"","frontmatter":{},"headers":[],"relativePath":"notes/paper-narrative-paradigms.md","filePath":"notes/paper-narrative-paradigms.md","lastUpdated":1791158645000}'),d={name:"notes/paper-narrative-paradigms.md"};function n(l,t,s,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="论文叙事六大范式" tabindex="-1">论文叙事六大范式 <a class="header-anchor" href="#论文叙事六大范式" aria-label="Permalink to &quot;论文叙事六大范式&quot;">​</a></h1><blockquote><p>📖 读书笔记 · 来源：公众号「人工智能学社」<a href="https://mp.weixin.qq.com/s/mnU8PE-6DZ38rJqHeOiSfQ" target="_blank" rel="noreferrer">《Story Is All You Need：扒透 35 篇顶会最佳/杰出论文的叙事密码，我们找到了六大范式》</a> 整理于 2026-10-05 · 版权归原作者所有，本文为个人学习摘要，完整论述与 35 篇论文索引请看原文</p></blockquote><h2 id="核心论点" tabindex="-1">核心论点 <a class="header-anchor" href="#核心论点" aria-label="Permalink to &quot;核心论点&quot;">​</a></h2><p>2026 年 AI 顶会投稿量破万（CVPR、AAAI、ICLR、NeurIPS、ECCV 集体破万），审稿人平均不到半小时审一篇。当 SOTA 被大模型快速拉平（CVPR-2026 就有 4089 篇中稿，&quot;每年诞生至少 4 千个 SOTA&quot;）、编程/写作/裁缝式 idea 又被各类 Skill 抹平，<strong>胜负手已经从「指标高多少」转向「故事讲得多清楚、多反直觉、多让人信服」</strong>。</p><p>这里的「叙事」不是包装话术，而是研究思维方式：如何分析任务、定义问题、定位真因、用实验讲透因果链条。</p><h2 id="六大叙事范式" tabindex="-1">六大叙事范式 <a class="header-anchor" href="#六大叙事范式" aria-label="Permalink to &quot;六大叙事范式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>范式</th><th>一句话</th><th>代表论文</th></tr></thead><tbody><tr><td>①</td><td><strong>根因手术刀</strong></td><td>先定位经验现象背后的真因，再给方法</td><td>Lychee-FD（全双工语音的模态干扰根因→层次化参数分离）、STEER（熵坍缩四因素→自适应重加权）、GeoRA</td></tr><tr><td>②</td><td><strong>反直觉重构</strong></td><td>推翻领域默认设定，给更优雅替代</td><td>D4RT（CVPR Best：统一查询接口同时出深度/点云/相机）、HKTex（ECCV Best：抛弃 UV 展开，测地高斯）、「灵活性陷阱」（扩散 LM 的卖点重新讲成缺陷）</td></tr><tr><td>③</td><td><strong>理论照亮经验</strong></td><td>用数学/形式化证明解释为什么有效</td><td>Transformers are Inherently Succinct（ICLR）、局部注意力表达能力（ACL，形式语言一锤定音）、Model Change（AAAI）</td></tr><tr><td>④</td><td><strong>新基准暴露失效</strong></td><td>造更锋利的尺子，量出被忽略的漏洞</td><td>CAR-Bench（车载 Agent 一致性，消歧任务通过率 &lt;50%）、MediEval（四象限测医学幻觉）、LLMs Get Lost（多轮对话顶级模型平均掉点 39%）</td></tr><tr><td>⑤</td><td><strong>社会价值叙事</strong></td><td>把技术钉在真实世界的痛点上</td><td>PlantTraitNet（全球植物性状基础模型，Best Social Impact）、Slum Detection/GRAM（跨城市棚户区监测）</td></tr><tr><td>⑥</td><td><strong>极简统一美学</strong></td><td>一个接口/一种表征通吃多任务</td><td>ReconVLA（重建观测作辅助目标）、LLM2CLIP（LLM 长描述蒸馏进 CLIP）、High-Pass/Sheaflet</td></tr></tbody></table><p>一篇好论文常同时踩中两三条，但总有一条是主线。</p><h2 id="写论文前的六问自检清单" tabindex="-1">写论文前的六问自检清单 <a class="header-anchor" href="#写论文前的六问自检清单" aria-label="Permalink to &quot;写论文前的六问自检清单&quot;">​</a></h2><ol><li><strong>先找根因再给方法</strong> —— 别只堆指标，先讲清「现有方法为什么翻车」</li><li><strong>用反直觉做钩子</strong> —— 挑战一个领域共识，比顺应共识更能抓人</li><li><strong>造更锋利的尺子</strong> —— 新基准/新指标暴露真实漏洞，比刷分更显功力</li><li><strong>用理论解释经验</strong> —— 哪怕一个小引理，也能把玄学变硬通货</li><li><strong>把技术钉在痛点上</strong> —— 社会影响/应用价值是加分项，不是装饰</li><li><strong>追求极简统一</strong> —— 一个接口通吃，比 N 个模块更显功力</li></ol><h2 id="三类最容易被秒拒的叙事" tabindex="-1">三类最容易被秒拒的叙事 <a class="header-anchor" href="#三类最容易被秒拒的叙事" aria-label="Permalink to &quot;三类最容易被秒拒的叙事&quot;">​</a></h2><ol><li>只报 SOTA、不解释为什么；</li><li>跟风 + 裁缝，问题定义和原始方法都来自别人；</li><li>把「包装话术」当叙事——评审一眼看穿。</li></ol><blockquote><p>叙事本身是研究的副产品，不是投稿前的化妆。</p></blockquote><h2 id="我的一点延伸" tabindex="-1">我的一点延伸 <a class="header-anchor" href="#我的一点延伸" aria-label="Permalink to &quot;我的一点延伸&quot;">​</a></h2><p>这套范式对<strong>教程与技术写作</strong>同样成立：Jev Cookbook 每章坚持回答「这个实验在验证什么、观察到了什么、不能由此推出什么」，本质上就是范式 ③ + ④ 的科普版——用实验数据说话，把「看起来合理」变成「结果究竟怎样」。</p><ul><li><a href="/notes/">返回笔记目录</a></li></ul>',16)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
